const $=s=>document.querySelector(s);
const byId=id=>works.find(w=>w.id===id);
function imageMarkup(id,original=false){const w=byId(id);return '<span class="art-window '+(w.category==='ceramics'&&!original?'rotated':'')+(original?' original':'')+'"><img src="assets/'+id+'.webp" alt="'+w.alt+'" loading="lazy"></span>'}
function artButton(id,extra=''){return '<button class="art-button '+extra+'" data-art="'+id+'" aria-label="Zobacz: '+byId(id).title+'">'+imageMarkup(id)+'<span class="enlarge" aria-hidden="true">↗</span></button>'}
function card(w,i){return '<figure>'+artButton(w.id)+'<figcaption><span><small>'+String(i+1).padStart(2,'0')+'</small>'+w.title+'</span><em>'+w.meta+'</em></figcaption></figure>'}
