$('#top').innerHTML=intros[concept]+gallerySection+discoveries+about+cv+contact;
let filtered=[],viewSet=[],current=0,lastTrigger,showOriginal=false;
const descriptions={ceramics:'Forma, powierzchnia i dekoracja graficzna. Ceramika artystyczna.',painting:'Martwe natury w akwareli i oleju. Prace z 2017 roku.',graphics:'Autorskie prace graficzne i kompozycje geometryczne.'};
function filter(category){filtered=works.filter(w=>w.category===category);$('#gallery').innerHTML=filtered.map(card).join('');$('#gallery').dataset.category=category;$('#gallery').scrollLeft=0;$('#work-count').textContent=String(filtered.length).padStart(2,'0')+' / PRAC';$('#category-description').textContent=descriptions[category];document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===category);b.setAttribute('aria-pressed',String(b.dataset.filter===category))});bindArt($('#gallery'))}
function bindArt(parent){parent.querySelectorAll('[data-art]').forEach(b=>b.addEventListener('click',()=>openArt(b.dataset.art,b)))}
function openArt(id,button){viewSet=filtered.some(w=>w.id===id)?filtered:works.filter(w=>w.category===byId(id).category);current=viewSet.findIndex(w=>w.id===id);lastTrigger=button;showOriginal=false;updateViewer();$('#viewer').showModal();document.body.classList.add('modal-open');$('#close-viewer').focus()}
function updateViewer(){const w=viewSet[current];$('#viewer-image').innerHTML=imageMarkup(w.id,showOriginal);$('#viewer-image img').loading='eager';$('#viewer-title').textContent=w.title;$('#viewer-meta').textContent=w.meta;$('#viewer-position').textContent=String(current+1).padStart(2,'0')+' / '+String(viewSet.length).padStart(2,'0');$('#original').hidden=w.category!=='ceramics';$('#original').textContent=showOriginal?'Widok galeryjny':'Oryginalne zdjęcie';$('#original').setAttribute('aria-pressed',String(showOriginal))}
function next(n){current=(current+n+viewSet.length)%viewSet.length;showOriginal=false;updateViewer()}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>filter(b.dataset.filter));
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{filter(b.dataset.go);$('#works').scrollIntoView({behavior:'smooth'});document.querySelector('[data-filter="'+b.dataset.go+'"]').focus({preventScroll:true})});
bindArt($('#top'));filter('ceramics');
$('#previous-art').onclick=()=>next(-1);$('#next-art').onclick=()=>next(1);$('#original').onclick=()=>{showOriginal=!showOriginal;updateViewer()};$('#close-viewer').onclick=()=>$('#viewer').close();$('#viewer').addEventListener('close',()=>{document.body.classList.remove('modal-open');lastTrigger?.focus()});$('#viewer').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();next(-1)}if(e.key==='ArrowRight'){e.preventDefault();next(1)}});$('#viewer').addEventListener('click',e=>{if(e.target===$('#viewer')){const r=$('#viewer').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#viewer').close()}});
$('#menu-toggle').onclick=()=>{const open=$('#menu-toggle').getAttribute('aria-expanded')!=='true';$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#main-nav').classList.toggle('open',open)};$('#main-nav').querySelectorAll('a').forEach(a=>a.onclick=()=>{$('#main-nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false')});
$('#hide-compare').onclick=()=>{$('.compare').hidden=true;$('#show-compare').hidden=false};$('#show-compare').onclick=()=>{$('.compare').hidden=false;$('#show-compare').hidden=true};

